note.ddx:
{
  "step1_summary": [
    "Chief complaint: Sudden-onset dizziness/vertigo (“room is spinning”) with nausea.",
    "Symptom details: • Started ≈2 h prior while making breakfast; continuous since onset. • Similar brief episode 1 mo ago (5–10 min). • Associated ear buzzing/tinnitus. • Feels unsteady but no true limb weakness. • No vomiting yet, no headache, no ear pain/discharge, no recent viral illness, no fever.",
    "Past medical history: Premature ovarian failure; on hormone-replacement therapy (HRT). No other chronic diseases noted.",
    "Medications/allergies: HRT; no other regular meds. Denies drug allergies.",
    "Family/social history: Married; no other details reported (smoking, alcohol, vascular risk factors not discussed).",
    "Vital signs/exam: Video visit only; vitals not measured. Patient reports intact motor strength, able to ambulate but veers because of vertigo. No focal neuro deficits elicited.",
    "Labs/imaging: None performed or mentioned during visit."
  ],
  "step2_vindicate": {
    "V": [
      "Cerebellar or vertebrobasilar ischemic stroke/TIA: acute vertigo with gait unsteadiness could reflect posterior-circulation event, especially if continuous.",
      "Vertebral artery dissection: can present with acute vertigo in younger patients without classic risk factors."
    ],
    "I": [
      "Vestibular neuritis / viral labyrinthitis: inflammation of vestibular nerve/inner ear causes hours–days of vertigo, nausea, tinnitus.",
      "Acute otitis media/interna: middle/inner-ear infection may give vertigo, although ear pain/discharge are absent."
    ],
    "N": [
      "Vestibular schwannoma (acoustic neuroma): progressive tinnitus ± episodic vertigo, though typically chronic.",
      "Posterior-fossa tumor (e.g., cerebellar): chronic dizziness/unsteadiness."
    ],
    "D": [
      "Benign paroxysmal positional vertigo (BPPV): otolith degeneration causes vertigo often seconds–minutes with head movement.",
      "Age-related cervical spondylosis causing vertebrobasilar insufficiency on rotation."
    ],
    "I2": [
      "Drug-induced vertigo (e.g., ototoxic meds, alcohol): not likely—no offending agents reported.",
      "HRT-related thrombotic event (rare) leading to stroke/TIA."
    ],
    "C": [
      "Congenital semicircular-canal malformation: usually lifelong history, unlikely new at age 42."
    ],
    "A": [
      "Ménière’s disease (autoimmune inner-ear hydrops): recurrent vertigo, tinnitus, hearing fluctuation.",
      "Multiple sclerosis: demyelinating lesions can cause acute vestibular syndrome."
    ],
    "T": [
      "Post-traumatic vestibulopathy/concussion: no recent head injury reported."
    ],
    "E": [
      "Hypoglycemia: can cause dizziness, shakiness, nausea.",
      "Anemia: nonspecific dizziness; unlikely to cause true spinning vertigo."
    ]
  },
  "step3_ranked_ddx": [
    {
      "diagnosis": "Vestibular neuritis / viral labyrinthitis",
      "likelihood": "High",
      "explanation": "Classic acute vestibular syndrome with continuous spinning vertigo, nausea, tinnitus, gait unsteadiness, and no focal neurologic deficits fits vestibular neuritis/labyrinthitis best."
    },
    {
      "diagnosis": "Ménière’s disease",
      "likelihood": "Medium",
      "explanation": "Recurrent episodes (prior 5-10 min event; current longer) plus tinnitus are compatible, though absence of fluctuating hearing loss and longer current episode make it less likely."
