    {
      "diagnosis": "Benign paroxysmal positional vertigo (BPPV)",
      "likelihood": "Medium-Low",
      "explanation": "Very common cause of vertigo; however attacks are usually brief (<1 min) and triggered by position changes, which patient does not report. Still considered because of age and prior transient episode."
    },
    {
      "diagnosis": "Posterior-circulation (cerebellar) stroke/TIA",
      "likelihood": "Low-Medium",
      "explanation": "Acute persistent vertigo with imbalance could signal cerebellar ischemia; lack of focal deficits lowers probability but does not exclude, especially without exam/vitals."
    },
    {
      "diagnosis": "Hypoglycemia",
      "likelihood": "Low",
      "explanation": "Shakiness and dizziness can occur, but true spinning vertigo is uncommon; no diabetes or medication risk noted."
    }
  ],
