        "Associated nausea, tinnitus",
        "No focal limb weakness or other neurologic deficits"
      ],
      "opposing_evidence": [
        "No preceding viral illness reported",
        "No hearing loss (labyrinthitis often has hearing loss, though vestibular neuritis does not)"
      ]
    },
    "Ménière’s disease": {
      "supporting_evidence": [
        "Recurrent vertigo (episode one month ago)",
        "Tinnitus present"
      ],
      "opposing_evidence": [
        "No documented fluctuating or reduced hearing",
        "Current episode longer than typical 20 min–12 h Ménière’s range but prior was very short"
      ]
    },
    "Benign paroxysmal positional vertigo": {
      "supporting_evidence": [
